"""Text helpers shared by the claim form and the ledger bridge."""
import unicodedata

_SPACES = {"\t", "\n", "\r", "\x0b", "\x0c", " ", "　"}


def normalize(text):
    """NFC-normalize, turn odd whitespace into plain spaces, collapse runs."""
    if text is None:
        return ""
    text = unicodedata.normalize("NFC", str(text))
    out = []
    for ch in text:
        if ch in _SPACES:
            ch = " "
        elif unicodedata.category(ch) == "Cc":
            continue
        if ch == " " and out and out[-1] == " ":
            continue
        out.append(ch)
    return "".join(out).strip()


def clip_chars(text, limit):
    """Cut text to at most `limit` characters (never splits a character)."""
    if limit <= 0:
        return ""
    if len(text) <= limit:
        return text
    return text[:limit].rstrip()


def display_width(text):
    """Terminal/report column width: East Asian wide characters count as 2."""
    width = 0
    for ch in text:
        width += 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
    return width


def pad_display(text, width):
    """Pad (or cut) text so that it occupies exactly `width` report columns."""
    out, used = [], 0
    for ch in text:
        w = display_width(ch)
        if used + w > width:
            break
        out.append(ch)
        used += w
    return "".join(out) + " " * (width - used)
"""Turns an approved expense claim into a ledger entry."""
from hbexpense.models import LedgerEntry
from hbexpense.util.text import clip_chars, normalize


def compose_memo(claim):
    """Memo shown to the finance team: claim id, claimant, what it was for."""
    parts = [claim.claim_id, claim.claimant, claim.description]
    return normalize(" ".join(p for p in parts if p))


def build_entry(claim, settings):
    account = settings.accounts.get(claim.category)
    if account is None:
        raise ValueError(f"no ledger account for category {claim.category}")
    memo = clip_chars(compose_memo(claim), settings.ledger_memo_chars)
    return LedgerEntry(
        account=account,
        amount=claim.amount,
        date=claim.spent_on,
        ref=claim.claim_id,
        memo=memo,
    )
"""Runtime settings. Values can be overridden through build_app(**overrides)."""
import os
from dataclasses import dataclass, field, replace

_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def _default_ledger_bin():
    return os.environ.get("HB_LEDGER_BIN", os.path.join(_ROOT, "vendor", "bin", "ledgerctl"))


@dataclass(frozen=True)
class Settings:
    # vendor ledger CLI
    ledger_bin: str = field(default_factory=_default_ledger_bin)
    ledger_home: str = ""
    ledger_timeout: float = 10.0
    # claim form rules (expense portal screen spec v3)
    description_max_chars: int = 30
    claimant_max_chars: int = 10
    max_amount: int = 5_000_000
    # ledger memo column as agreed with the finance team
    ledger_memo_chars: int = 40
    # category -> ledger account code
    accounts: dict = field(default_factory=lambda: {
        "TRAVEL": "5110",
        "MEAL": "5120",
        "SUPPLIES": "5130",
        "TRAINING": "5140",
        "COMMS": "5150",
    })
    report_cache_ttl: float = 60.0

    def with_overrides(self, **overrides):
        unknown = set(overrides) - set(self.__dataclass_fields__)
        if unknown:
            raise KeyError(f"unknown settings: {sorted(unknown)}")
        return replace(self, **overrides)


DEFAULTS = Settings()
